"""Migrated Meridian CRM 4.2 case_lifecycle workflow."""

from __future__ import annotations

from typing import Any


def _value(record: dict[str, Any], field: str) -> Any:
    """Return a VRL field value; missing values are empty strings."""
    return record.get(field, "")


def _nonempty_owner(record: dict[str, Any]) -> bool:
    return _value(record, "OWNER_UID") != ""


def _not_escalated(record: dict[str, Any]) -> bool:
    return _value(record, "ESC_FLG") != "Y"


def _resolved_date_present(record: dict[str, Any]) -> bool:
    return _value(record, "RES_DT") != "00000000"


def _nvl(value: Any, default: str) -> Any:
    """VRL NVL: missing or empty values use the supplied default."""
    return default if value == "" else value


def fire(state: str, event: str, record: dict) -> dict:
    """
    Dispatch an explicit case_lifecycle workflow event.

    The input record is never modified.  Timers are intentionally not evaluated;
    this function only handles events that have already been posted.
    """
    updated = dict(record)

    # Transition document order is preserved below.
    if state == "N" and event == "assign" and _nonempty_owner(updated):
        return {
            "state": "A",
            "record": updated,
            "audits": ["CASE_ASSIGN"],
            "notifies": [],
            "matched": True,
        }

    if state == "N" and event == "auto_escalate":
        updated["ESC_FLG"] = "Y"
        updated["SEV_CD"] = _nvl(_value(updated, "SEV_CD"), "3")
        return {
            "state": "A",
            "record": updated,
            "audits": ["CASE_ESC"],
            "notifies": ["escalation"],
            "matched": True,
        }

    if state == "A" and event == "auto_escalate" and _not_escalated(updated):
        updated["ESC_FLG"] = "Y"
        return {
            "state": "A",
            "record": updated,
            "audits": ["CASE_ESC"],
            "notifies": ["escalation"],
            "matched": True,
        }

    if state == "A" and event == "await_customer":
        return {
            "state": "P",
            "record": updated,
            "audits": ["CASE_PEND"],
            "notifies": [],
            "matched": True,
        }

    if state == "P" and event == "customer_reply":
        return {
            "state": "A",
            "record": updated,
            "audits": [],
            "notifies": [],
            "matched": True,
        }

    if state == "A" and event == "resolve" and _resolved_date_present(updated):
        return {
            "state": "R",
            "record": updated,
            "audits": ["CASE_RES"],
            "notifies": [],
            "matched": True,
        }

    if state == "R" and event == "close":
        return {
            "state": "X",
            "record": updated,
            "audits": ["CASE_CLOSE"],
            "notifies": [],
            "matched": True,
        }

    if state == "R" and event == "reopen":
        updated["RES_DT"] = "00000000"
        return {
            "state": "A",
            "record": updated,
            "audits": ["CASE_REOPEN"],
            "notifies": [],
            "matched": True,
        }

    return {
        "state": state,
        "record": updated,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
